add_filter( 'upload_mimes', 'perfectpixel_allow_svg_mimes' );
add_filter( 'wp_check_filetype_and_ext', 'perfectpixel_allow_svg_filetype', 10, 4 );
add_filter( 'wp_handle_upload_prefilter', 'perfectpixel_check_svg_upload' );

function perfectpixel_allow_svg_mimes( $mimes ) {
	if ( current_user_can( 'manage_options' ) ) {
		$mimes['svg'] = 'image/svg+xml';
	}
	return $mimes;
}

function perfectpixel_allow_svg_filetype( $data, $file, $filename, $mimes ) {
	if ( current_user_can( 'manage_options' ) && 'svg' === strtolower( pathinfo( $filename, PATHINFO_EXTENSION ) ) ) {
		$data['ext']  = 'svg';
		$data['type'] = 'image/svg+xml';
	}
	return $data;
}

function perfectpixel_check_svg_upload( $file ) {
	if ( 'svg' !== strtolower( pathinfo( $file['name'], PATHINFO_EXTENSION ) ) ) {
		return $file;
	}
	if ( ! current_user_can( 'manage_options' ) ) {
		$file['error'] = 'Δεν επιτρέπεται το ανέβασμα SVG.';
		return $file;
	}
	$svg = (string) file_get_contents( $file['tmp_name'] );
	if ( preg_match( '/<script|\son\w+\s*=|javascript:|<foreignObject|<!ENTITY|xlink:href\s*=\s*["\']\s*(?!#|data:image)/i', $svg ) ) {
		$file['error'] = 'Το SVG περιέχει scripts ή εξωτερικό περιεχόμενο και απορρίφθηκε για λόγους ασφαλείας.';
	}
	return $file;
}
